-- 17A POSTCHECKS P6 state POST: one read-only statement; ok must be true on every row
-- 17A STORAGE PRIVACY: PROPOSAL ONLY. NOT APPLIED ANYWHERE. GENERATED by db/proposed/17a-storage-privacy/build.mjs (node build.mjs --check fails if this file drifts from its inputs).
-- Apply gate: NO prod SQL and NO Storage API operation without Joe's relayed yes + Sentinel's pass + Atlas's review of the migrations + a backup. Sentinel's inventory/backup files were NOT available to this draft (see README). Order: README.md.
-- Run as postgres, ONE transaction, ON_ERROR_STOP (psql -v ON_ERROR_STOP=1) or a single-call SQL executor; right after BEGIN come SET LOCAL lock_timeout = '5s', the repo-wide pack advisory lock, and SET LOCAL lock_timeout = '5s' again.
-- Read-only (a single SELECT over the catalog; the scan in P3c reads counts only).
WITH a(name, actual) AS (
  SELECT 'req.vs_is_admin_exists' AS name, coalesce((to_regprocedure('public.vs_is_admin()') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_is_admin_exec_authenticated' AS name, coalesce((SELECT has_function_privilege('authenticated', to_regprocedure('public.vs_is_admin()'), 'EXECUTE')::text), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_cols' AS name, coalesce((SELECT count(*)::text FROM unnest(ARRAY['id','status']) c WHERE EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.vs_entries') AND a.attname = c AND NOT a.attisdropped)), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_id_bigint' AS name, coalesce((SELECT format_type(a.atttypid, a.atttypmod) FROM pg_attribute a WHERE a.attrelid = 'public.vs_entries'::regclass AND a.attname = 'id'), 'ABSENT') AS actual
  UNION ALL SELECT 'req.vs_entries_public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'fn.vs_entry_media_is_approved' AS name, coalesce((to_regprocedure('public.vs_entry_media_is_approved(text)') IS NOT NULL)::text, 'ABSENT') AS actual
  UNION ALL SELECT 'fn.secdef_owner_config' AS name, coalesce((SELECT p.prosecdef::text || '/' || pg_get_userbyid(p.proowner) || '/' || coalesce((SELECT string_agg(c,',') FROM unnest(p.proconfig) c),'(none)') FROM pg_proc p WHERE p.oid = to_regprocedure('public.vs_entry_media_is_approved(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'fn.exec_anon_authenticated_public' AS name, coalesce((SELECT has_function_privilege('anon', p.oid, 'EXECUTE')::text || '/' || has_function_privilege('authenticated', p.oid, 'EXECUTE')::text || '/' || coalesce((SELECT bool_or(x.grantee = 0) FROM aclexplode(p.proacl) x), false)::text FROM pg_proc p WHERE p.oid = to_regprocedure('public.vs_entry_media_is_approved(text)')), 'ABSENT') AS actual
  UNION ALL SELECT 'sel.vs-entries' AS name, coalesce((SELECT coalesce(string_agg(p.policyname::text, ',' ORDER BY p.policyname::text COLLATE "C"),'(none)') FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.cmd IN ('SELECT','ALL') AND (coalesce(p.qual,'') || ' ' || coalesce(p.with_check,'')) ~ 'vs-entries'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_reviewer_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_reviewer_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'pol.vs_media_approved_read.shape' AS name, coalesce((SELECT p.cmd || '|' || array_to_string(p.roles, ',') || '|' || p.permissive FROM pg_policies p WHERE p.schemaname = 'storage' AND p.tablename = 'objects' AND p.policyname = 'vs_media_approved_read'), 'ABSENT') AS actual
  UNION ALL SELECT 'bucket.vs-entries.public' AS name, coalesce((SELECT b.public::text FROM storage.buckets b WHERE b.id = 'vs-entries'), 'ABSENT') AS actual
), e(name, expected, accepted) AS (VALUES
  ('req.vs_is_admin_exists', 'true', ARRAY['true']::text[]),
  ('req.vs_is_admin_exec_authenticated', 'true', ARRAY['true']::text[]),
  ('req.vs_entries_cols', '2', ARRAY['2']::text[]),
  ('req.vs_entries_id_bigint', 'bigint', ARRAY['bigint']::text[]),
  ('req.vs_entries_public', 'true', ARRAY['true']::text[]),
  ('fn.vs_entry_media_is_approved', 'true', ARRAY['true']::text[]),
  ('fn.secdef_owner_config', 'true/postgres/search_path=""', ARRAY['true/postgres/search_path=""']::text[]),
  ('fn.exec_anon_authenticated_public', 'true/true/false', ARRAY['true/true/false']::text[]),
  ('sel.vs-entries', 'vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read', ARRAY['vs_media_approved_read,vs_media_owner_admin_read,vs_media_reviewer_read']::text[]),
  ('pol.vs_media_reviewer_read.shape', 'SELECT|authenticated|PERMISSIVE', ARRAY['SELECT|authenticated|PERMISSIVE']::text[]),
  ('pol.vs_media_approved_read.shape', 'SELECT|anon,authenticated|PERMISSIVE', ARRAY['SELECT|anon,authenticated|PERMISSIVE']::text[]),
  ('bucket.vs-entries.public', 'true', ARRAY['true']::text[])
), r AS (SELECT e.name, coalesce(e.expected, 'RECORD ONLY') AS expected, a.actual, (e.accepted IS NULL OR a.actual = ANY (e.accepted)) AS ok FROM e LEFT JOIN a USING (name))
SELECT '000_ALL_OK' AS name, 'POST' AS expected, 'POST' AS actual, bool_and(ok) AS ok FROM r
UNION ALL SELECT name, expected, actual, ok FROM r
ORDER BY 1;
